<template><div v-if="lesson"><PageHero :title="lesson.title" :subtitle="lesson.summary" :image="lesson.cover" :eyebrow="`${lesson.category} · ${lesson.duration}`"/><main class="page"><el-breadcrumb separator="/"><el-breadcrumb-item to="/">首页</el-breadcrumb-item><el-breadcrumb-item to="/videos">红色影像馆</el-breadcrumb-item><el-breadcrumb-item>{{ lesson.title }}</el-breadcrumb-item></el-breadcrumb><section class="player-wrap"><MotionStory :title="lesson.title" :frames="lesson.frames" :captions="lesson.frameCaptions" :frame-types="lesson.frameTypes"/><div class="transcript panel"><h2>完整讲解稿</h2><p>{{ lesson.transcript }}</p><dl><div><dt>制作方式</dt><dd>本地图片、字幕与网页动画</dd></div><div><dt>专题对应</dt><dd>{{ lesson.category }} · {{ lesson.title }}</dd></div><div><dt>来源</dt><dd>{{ lesson.source }}</dd></div><div><dt>版权说明</dt><dd>画面许可与来源见图片资料页；项目自制画面不标作历史原图。</dd></div><div><dt>声音</dt><dd>默认静音，可使用浏览器音频讲解模块</dd></div></dl><RouterLink to="/audio">打开音频讲解</RouterLink></div></section><h2 class="section-title">相关推荐</h2><div class="grid grid-3"><RouterLink v-for="item in related" :key="item.slug" :to="`/videos/${item.slug}`" class="recommend panel"><SafeImage :src="item.cover" :alt="item.title"/><strong>{{ item.title }}</strong><span>{{ item.duration }}</span></RouterLink></div></main></div><NotFound v-else/></template>
<script setup>import{computed}from'vue';import{RouterLink,useRoute}from'vue-router';import PageHero from'../components/PageHero.vue';import MotionStory from'../components/MotionStory.vue';import SafeImage from'../components/SafeImage.vue';import NotFound from'./NotFound.vue';import{getVideoLesson,videoLessons}from'../data/experienceContent';const route=useRoute();const lesson=computed(()=>getVideoLesson(route.params.slug));const related=computed(()=>videoLessons.filter(i=>i.slug!==lesson.value?.slug).slice(0,3))</script>
<style scoped>.player-wrap{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,.7fr);gap:24px;margin:24px 0 50px}.player-wrap .motion-story{min-height:500px}.transcript{padding:24px}.transcript h2{color:var(--red-dark)}.transcript p{line-height:2;color:var(--muted)}.transcript dl{display:grid;gap:12px}.transcript dl div{padding:10px 0;border-top:1px solid var(--line)}.transcript dt{color:var(--gold)}.transcript dd{margin:5px 0}.transcript a{display:inline-flex;margin-top:16px;padding:10px 14px;color:#fff;background:var(--red);border-radius:8px}.recommend{display:grid;overflow:hidden}.recommend :deep(.safe-image){height:180px}.recommend strong,.recommend span{margin:12px 16px 0}.recommend span{margin-bottom:16px;color:var(--gold)}@media(max-width:900px){.player-wrap{grid-template-columns:1fr}.player-wrap .motion-story{min-height:420px}}</style>
